export const PHASES=Object.freeze(["loading","checkin","race","results"]);const t=Object.freeze({loading:Object.freeze({loaded:"checkin"}),checkin:Object.freeze({go:"race"}),race:Object.freeze({finish:"results",skip:"results",back:"checkin"}),results:Object.freeze({again:"race",another:"checkin",back:"checkin"})});export function nextPhase(e,r){const c=t[e];return c&&c[r]||e}
